const m = JSON.parse($('Ler modelo').first().json.metadata);
m.elabftw = m.elabftw || {};
const grupos = m.elabftw.extra_fields_groups || [];
if (!grupos.some((g) => g.id === 2)) grupos.push({ id: 2, name: 'Depósito no Zenodo' });
m.elabftw.extra_fields_groups = grupos;
const ef = m.extra_fields;
const novos = {
  'Autores': { type: 'text', value: '', group_id: 2, position: 1,
    description: 'Separe os autores com |. Cada um: Sobrenome, Nome; vínculo; ORCID (opcional). Ex.: Silva, Ana; Instituto Modal; 0000-0002-1825-0097 | Souza, Beto; Empresa X' },
  'Resumo': { type: 'text', value: '', group_id: 2, position: 2, description: 'Resumo do produto, como vai aparecer no Zenodo.' },
  'Palavras-chave': { type: 'text', value: '', group_id: 2, position: 3, description: 'Separadas por ponto e vírgula.' },
  'Depositar no Zenodo': { type: 'checkbox', value: '', group_id: 2, position: 4,
    description: 'Marque depois da revisão editorial, com o PDF final anexado. Cria um rascunho no Zenodo do Instituto (não publica) e grava o DOI reservado.' },
};
for (const [k, v] of Object.entries(novos)) if (!ef[k]) ef[k] = v;
return [{ json: { metadata: JSON.stringify(m) } }];
